from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

CENT = Decimal("0.01")
BRACKETS = [
    (Decimal("0"), Decimal("12450"), 19),
    (Decimal("12450"), Decimal("20200"), 24),
    (Decimal("20200"), Decimal("35200"), 30),
    (Decimal("35200"), Decimal("60000"), 37),
    (Decimal("60000"), Decimal("300000"), 45),
    (Decimal("300000"), None, 47),
]

# Bracket bounds in integer cents (exact, small values).
_BRACKETS_CENTS = [
    (0, 12450 * 100, 19),
    (12450 * 100, 20200 * 100, 24),
    (20200 * 100, 35200 * 100, 30),
    (35200 * 100, 60000 * 100, 37),
    (60000 * 100, 300000 * 100, 45),
    (300000 * 100, None, 47),
]


def _parse_income_cents(income):
    if not isinstance(income, str):
        raise ValueError("income must be a string")
    try:
        amount = Decimal(income)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid income: {income!r}") from None
    if not amount.is_finite():
        raise ValueError("income must be finite")
    if amount < 0:
        raise ValueError("income must be >= 0")
    t = amount.as_tuple()
    e = t.exponent
    digits = t.digits
    if digits == (0,) or (len(digits) == 1 and digits[0] == 0):
        signed = 0
    else:
        s = int("".join(map(str, digits)))
        signed = -s if t.sign else s
    if signed == 0:
        # Zero in any representation (e.g. "0", "0.00", "0.000") is valid
        # and equals 0 cents numerically.
        income_cents = 0
    elif e >= -2:
        income_cents = signed * (10 ** (e + 2))
    else:
        extra = -e - 2
        div = 10 ** extra
        if signed % div != 0:
            raise ValueError("income must have at most 2 decimal places")
        income_cents = signed // div
    if income_cents < 0:
        raise ValueError("income must be >= 0")
    return income_cents


def _cents_to_2dp(cents):
    return Decimal(cents).scaleb(-2)


def _parse_income(income):
    return _cents_to_2dp(_parse_income_cents(income))


def tax_breakdown(income):
    income_cents = _parse_income_cents(income)
    rows = []
    for lower_cents, upper_cents, rate in _BRACKETS_CENTS:
        if income_cents <= lower_cents:
            continue
        top = income_cents if upper_cents is None else min(income_cents, upper_cents)
        taxable_cents = top - lower_cents
        if taxable_cents <= 0:
            continue
        # tax in cents = taxable_cents * rate / 100, ROUND_HALF_UP.
        n = taxable_cents * rate
        tax_cents = (n + 50) // 100
        lower_d = _cents_to_2dp(lower_cents)
        upper_d = None if upper_cents is None else _cents_to_2dp(upper_cents)
        rows.append(
            {
                "from": lower_d,
                "to": upper_d,
                "rate_percent": rate,
                "taxable": _cents_to_2dp(taxable_cents),
                "tax": _cents_to_2dp(tax_cents),
            }
        )
    return rows


def income_tax(income):
    income_cents = _parse_income_cents(income)
    total_tax_cents = 0
    for lower_cents, upper_cents, rate in _BRACKETS_CENTS:
        if income_cents <= lower_cents:
            continue
        top = income_cents if upper_cents is None else min(income_cents, upper_cents)
        taxable_cents = top - lower_cents
        if taxable_cents <= 0:
            continue
        n = taxable_cents * rate
        total_tax_cents += (n + 50) // 100
    return _cents_to_2dp(total_tax_cents)


def effective_rate_percent(income):
    income_cents = _parse_income_cents(income)
    if income_cents == 0:
        return Decimal("0.0000")
    income_cents_check = income_cents
    total_tax_cents = 0
    for lower_cents, upper_cents, rate in _BRACKETS_CENTS:
        if income_cents_check <= lower_cents:
            continue
        top = income_cents_check if upper_cents is None else min(income_cents_check, upper_cents)
        taxable_cents = top - lower_cents
        if taxable_cents <= 0:
            continue
        total_tax_cents += (taxable_cents * rate + 50) // 100
    # rate = tax / income * 100; scaled by 10000 for 4dp with HALF_UP.
    scaled = total_tax_cents * 1000000
    q, r = divmod(scaled, income_cents)
    if 2 * r >= income_cents:
        q += 1
    return Decimal(q).scaleb(-4)
